<script setup>
import{ref,computed,onMounted,onUnmounted}from'vue';import{api,renderMarkdown,categoryNames,dateLabel}from'./cms-client';
const authorized=ref(false),ready=ref(false),busy=ref(false),uploading=ref(false),message=ref(''),error=ref(''),posts=ref([]),filter=ref(''),page=ref(1),total=ref(0),editor=ref(null),base=ref(''),preview=ref(false),bodyInput=ref(null),coverInput=ref(null),imageInput=ref(null);
const statusNames={draft:'草稿',published:'已发布',archived:'已归档'};
const dirty=computed(()=>editor.value&&JSON.stringify(editor.value)!==base.value);
const rendered=computed(()=>renderMarkdown(editor.value?.content));
const notify=(text)=>{message.value=text;error.value='';};
async function loadPosts(){const d=await api(`/api/admin/posts?page=${page.value}&status=${filter.value}`);posts.value=d.posts;total.value=d.total;}
async function changeFilter(value){filter.value=value;page.value=1;try{await loadPosts();}catch(e){error.value=e.message;}}
function leaveEditor(){return !dirty.value||window.confirm('当前内容还没有保存，确定放弃修改吗？');}
function create(){if(!leaveEditor())return;editor.value={id:null,title:'',content:'',excerpt:'',category:'article',status:'draft',tagsText:'',cover:'',version:0};base.value=JSON.stringify(editor.value);preview.value=false;message.value='';error.value='';}
async function edit(post){if(!leaveEditor())return;try{const p=(await api('/api/admin/posts/'+post.id)).post;editor.value={...p,tagsText:p.tags.join(', ')};base.value=JSON.stringify(editor.value);preview.value=false;message.value='';error.value='';}catch(e){error.value=e.message;}}
async function save(status){if(!editor.value||busy.value||uploading.value)return;busy.value=true;error.value='';message.value='';try{const body={...editor.value,status,tags:editor.value.tagsText.split(/[,，]/).map(s=>s.trim()).filter(Boolean)};const d=await api('/api/admin/posts'+(body.id?'/'+body.id:''),{method:body.id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});editor.value={...d.post,tagsText:d.post.tags.join(', ')};base.value=JSON.stringify(editor.value);notify(status==='published'?'已发布，网站已更新。':status==='archived'?'已归档，访客将看不到这篇内容。':'草稿已保存。');await loadPosts();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function upload(event,isCover){const file=event.target.files?.[0];event.target.value='';if(!file)return;if(file.size>5*1024*1024){error.value='图片不能超过 5 MB';return;}uploading.value=true;error.value='';try{const d=await api('/api/admin/uploads',{method:'POST',headers:{'Content-Type':file.type},body:file});if(isCover)editor.value.cover=d.url;else insert(`\n![图片说明](${d.url})\n`);notify(isCover?'封面已上传，请保存文章。':'图片已插入正文，请保存文章。');}catch(e){error.value=e.message;}finally{uploading.value=false;}}
function insert(text,before='',after=''){if(!editor.value)return;const el=bodyInput.value;if(!el){editor.value.content+=text;return;}const start=el.selectionStart,end=el.selectionEnd,selected=editor.value.content.slice(start,end);editor.value.content=editor.value.content.slice(0,start)+(before?before+(selected||text)+after:text)+editor.value.content.slice(end);}
function preventLeave(e){if(dirty.value){e.preventDefault();e.returnValue='';}}
function shortcut(e){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();if(editor.value)save(editor.value.status);}}
onMounted(async()=>{window.addEventListener('beforeunload',preventLeave);window.addEventListener('keydown',shortcut);try{await api('/api/admin/session');authorized.value=true;await loadPosts();}catch(e){if(e.status!==403)error.value=e.message;}finally{ready.value=true;}});
onUnmounted(()=>{window.removeEventListener('beforeunload',preventLeave);window.removeEventListener('keydown',shortcut);});
</script>
<template><div class="cms-admin"><header class="cms-heading"><div><span class="cms-eyebrow">NAIYAEL / WORKSPACE</span><h1>内容管理</h1><p>把想法写下来。</p></div><a href="/" class="cms-text-link">查看网站 ↗</a></header><p v-if="!ready" class="cms-muted">正在加载后台…</p><div v-else-if="!authorized" class="cms-login"><h2>欢迎回来</h2><p>使用你的 ChatGPT 账号登录后管理网站内容。</p><a class="cms-primary" href="/signin-with-chatgpt?return_to=%2Fadmin.html" target="_top">登录管理后台 →</a><p v-if="error" class="cms-error">{{error}}</p></div><template v-else><div class="cms-notification" role="status" v-if="message">✓ {{message}}</div><div class="cms-error cms-notification" role="alert" v-if="error">{{error}}</div><div class="cms-workspace"><aside class="cms-posts"><div class="cms-posts-header"><h2>我的内容 <small>{{total}}</small></h2><button class="cms-primary" @click="create">＋ 写一篇</button></div><div class="cms-filter"><button v-for="(label,key) in {all:'全部',draft:'草稿',published:'已发布',archived:'归档'}" :key="key" :class="{active:filter===(key==='all'?'':key)}" @click="changeFilter(key==='all'?'':key)">{{label}}</button></div><p v-if="!posts.length" class="cms-list-empty">这里还没有内容，写下第一篇吧。</p><button v-for="post in posts" :key="post.id" class="cms-post-row" :class="{selected:editor?.id===post.id}" @click="edit(post)"><strong>{{post.title}}</strong><span><i :class="post.status"></i>{{statusNames[post.status]}} · {{categoryNames[post.category]}}<time>{{dateLabel(post.updatedAt)}}</time></span></button><div class="cms-pagination" v-if="total>30"><button :disabled="page===1" @click="page--;loadPosts()">←</button><span>{{page}} / {{Math.ceil(total/30)}}</span><button :disabled="page*30>=total" @click="page++;loadPosts()">→</button></div></aside><section class="cms-editor" v-if="editor"><div class="cms-editor-top"><span :class="{'is-dirty':dirty}">{{dirty?'有未保存的修改':editor.id?'已保存':'新草稿'}}</span><div><button @click="save('draft')" :disabled="busy||uploading">{{busy?'保存中…':'保存草稿'}}</button><button class="cms-primary" @click="save('published')" :disabled="busy||uploading">{{editor.status==='published'?'更新发布':'发布文章'}} ↗</button></div></div><label class="cms-field"><span>标题</span><input v-model="editor.title" placeholder="写一个标题" maxlength="160" aria-label="文章标题"></label><div class="cms-field-row"><label class="cms-field"><span>分类</span><select v-model="editor.category" aria-label="文章分类"><option value="article">文章</option><option value="solution">题解</option><option value="daily">日常</option></select></label><label class="cms-field cms-tags-field"><span>标签</span><input v-model="editor.tagsText" placeholder="用逗号分隔，如 图论, 最短路" aria-label="文章标签"></label></div><label class="cms-field"><span>摘要 <small>可留空，保存时自动生成</small></span><textarea v-model="editor.excerpt" rows="2" maxlength="400" placeholder="用一两句话介绍这篇内容" aria-label="文章摘要"></textarea></label><div class="cms-cover-field"><span>封面 <small>可选</small></span><div><img v-if="editor.cover" :src="editor.cover" alt="文章封面预览"><button @click="coverInput.click()" :disabled="uploading">{{uploading?'上传中…':editor.cover?'更换封面':'＋ 上传封面'}}</button><button v-if="editor.cover" @click="editor.cover=''">移除</button></div></div><input ref="coverInput" type="file" accept="image/jpeg,image/png,image/webp,image/gif" hidden @change="upload($event,true)"><input ref="imageInput" type="file" accept="image/jpeg,image/png,image/webp,image/gif" hidden @change="upload($event,false)"><div class="cms-body-heading"><span>正文 <small>支持 Markdown</small></span><div><button :class="{active:!preview}" @click="preview=false">编辑</button><button :class="{active:preview}" @click="preview=true">预览</button></div></div><div class="cms-toolbar" v-if="!preview"><button @click="insert('小标题','\n## ','\n')">H₂ 标题</button><button @click="insert('加粗文字','**','**')"><b>B</b></button><button @click="insert('\n```cpp\n// 代码\n```\n')">&lt;/&gt; 代码</button><button @click="imageInput.click()" :disabled="uploading">＋ 图片</button></div><textarea v-if="!preview" ref="bodyInput" class="cms-body-input" v-model="editor.content" placeholder="从这里开始写…" aria-label="文章正文" spellcheck="false"></textarea><div class="vp-doc cms-body-preview" v-else v-html="rendered||'<p>正文预览会显示在这里。</p>'"></div><div class="cms-editor-bottom"><span>{{editor.content.length}} 字符</span><div><a v-if="editor.id&&editor.status==='published'" :href="`/post.html?id=${editor.id}`" target="_blank" rel="noopener noreferrer">查看文章 ↗</a><button v-if="editor.id&&editor.status!=='archived'" @click="save('archived')" :disabled="busy">归档</button></div></div></section><section class="cms-editor cms-start" v-else><span>✎</span><h2>今天，想写点什么？</h2><p>题解、笔记，或者普通的一天。</p><button class="cms-primary" @click="create">开始写作 →</button></section></div></template></div></template>

